Up(a,b){return a+" \xb7 \u0627\u0644\u062a\u0643\u0644\u0641\u0629 "+b},
gTM(){return"\u0627\u0644\u062d\u0642\u0648\u0644 \u0627\u0644\u0645\u062e\u0635\u0635\u0629"},
gUd(){return"\u062d\u0642\u0644 \u062c\u062f\u064a\u062f"},
guo(){return"\u0647\u0630\u0647 \u0647\u064a \u0627\u0644\u062d\u0642\u0648\u0644 \u0627\u0644\u062a\u064a \u062a\u064f\u0645\u0644\u0623 \u0644\u0647\u0630\u0647 \u0627\u0644\u0639\u0645\u0644\u064a\u0629 \u2014 \u0641\u064a \xab\u0639\u0645\u0644\u064a\u0629 \u062c\u062f\u064a\u062f\u0629\xbb\u060c \u0648\u0645\u0646 \u0645\u062e\u0637\u0637 \u0627\u0644\u0623\u0633\u0646\u0627\u0646\u060c \u0648\u0639\u0646\u062f \u062a\u0633\u062c\u064a\u0644 \u0632\u064a\u0627\u0631\u0629 (\u0645\u062b\u0644 \u0623\u0633\u0646\u0627\u0646 \u0627\u0644\u0628\u0627\u0644\u063a\u064a\u0646\u060c \u0627\u0644\u0642\u0648\u0633)."},
