gVM(){return"\u0628\u06c6 \u062f\u06a9\u062a\u06c6\u0631\u06ce\u06a9 \u062f\u0627\u0628\u0646\u0631\u06ce\u062a (\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5)"},
gVS(){return"\u0628\u06c6 \u0647\u06cc\u0686 \u062f\u06a9\u062a\u06c6\u0631\u06ce\u06a9 \u062f\u0627\u0646\u06d5\u0646\u0631\u0627\u0648\u06d5"},
gVT(){return"\u0647\u06ce\u0634\u062a\u0627 \u0647\u06cc\u0686 \u062c\u06c6\u0631\u06ce\u06a9\u06cc \u062a\u06ce\u0686\u0648\u0648 \u0646\u06cc\u06cc\u06d5 \u2014 \u0633\u06d5\u0631\u06d5\u062a\u0627 \u06cc\u06d5\u06a9\u06ce\u06a9 \u0632\u06cc\u0627\u062f \u0628\u06a9\u06d5."},
gFQ(){return"\u0628\u06d5\u0695\u06ce\u0648\u06d5\u0628\u0631\u062f\u0646\u06cc \u062c\u06c6\u0631\u06d5\u06a9\u0627\u0646\u06cc \u062a\u06ce\u0686\u0648\u0648"},
gVR(){return"\u062c\u06c6\u0631\u06cc \u062a\u06ce\u0686\u0648\u0648\u06cc \u0646\u0648\u06ce"},
gVP(){return"\u0646\u0627\u0686\u0627\u0644\u0627\u06a9\u06a9\u0631\u062f\u0646"},
