Y_(a){return"\u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u0627\u0646 ("+a+")"},
gGl(){return"\u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f"},
