gWc(){return"\u062a\u06cc\u0634\u06a9\u06ce\u06a9\u06cc \u062e\u06ce\u0631\u0627 \u0644\u06d5\u0633\u06d5\u0631 \u06a9\u0644\u06cc\u0646\u06cc\u06a9 \u0628\u06c6 \u0626\u06d5\u0645\u0695\u06c6."},
gW8(){return"\u06a9\u06c6\u06a9\u0631\u0627\u0648\u06d5"},
gW7(){return"\u067e\u0633\u0648\u06b5\u06d5\u06a9\u0631\u0627\u0648"},
