gWe(){return"\u062a\u06d5\u062e\u062a\u06d5\u06cc \u0626\u06d5\u0645\u0695\u06c6"},
gWa(){return"\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u067e\u06ce\u0634\u0648\u0627\u0632\u06cc"},
